import{_ as e,o as i,c as s,a2 as o}from"./chunks/framework.CHeM0PsO.js";const u=JSON.parse('{"title":"update","description":"","frontmatter":{},"headers":[],"relativePath":"es/cli/update.md","filePath":"es/cli/update.md","lastUpdated":1784904021000}'),t={name:"es/cli/update.md"};function c(n,a,l,d,r,p){return i(),s("div",null,[...a[0]||(a[0]=[o(`<h1 id="update" tabindex="-1">update <a class="header-anchor" href="#update" aria-label="Permalink to &quot;update&quot;">​</a></h1><h2 id="proposito" tabindex="-1">Propósito <a class="header-anchor" href="#proposito" aria-label="Permalink to &quot;Propósito&quot;">​</a></h2><p>Revalidar la configuración, limpiar la caché y volver a descargar todos los archivos de especificación. Esto es una <strong>actualización completa</strong> del espacio de trabajo — asegura que todas las especificaciones en caché estén actualizadas y el índice se reconstruya.</p><h2 id="cuando-usarlo" tabindex="-1">Cuándo usarlo <a class="header-anchor" href="#cuando-usarlo" aria-label="Permalink to &quot;Cuándo usarlo&quot;">​</a></h2><ul><li>Los archivos de especificación remotos han cambiado y desea la versión más reciente</li><li>Después de editar <code>swag2mcp.yaml</code> para agregar o cambiar ubicaciones de especificaciones</li><li>Al solucionar problemas de caché obsoleta o corrupta</li><li>Antes de ejecutar <code>mcp</code> para asegurarse de que todo esté actualizado</li></ul><h2 id="sintaxis" tabindex="-1">Sintaxis <a class="header-anchor" href="#sintaxis" aria-label="Permalink to &quot;Sintaxis&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [path]</span></span></code></pre></div><h2 id="argumentos" tabindex="-1">Argumentos <a class="header-anchor" href="#argumentos" aria-label="Permalink to &quot;Argumentos&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Argumento</th><th>Posición</th><th>Requerido</th><th>Descripción</th></tr></thead><tbody><tr><td><code>path</code></td><td>1</td><td>No</td><td>Directorio del espacio de trabajo. Si se omite, se resuelve mediante reglas de resolución de ruta.</td></tr></tbody></table><h2 id="banderas" tabindex="-1">Banderas <a class="header-anchor" href="#banderas" aria-label="Permalink to &quot;Banderas&quot;">​</a></h2><p>Ninguna.</p><h2 id="como-funciona" tabindex="-1">Cómo funciona <a class="header-anchor" href="#como-funciona" aria-label="Permalink to &quot;Cómo funciona&quot;">​</a></h2><p>El comando <code>update</code> ejecuta un pipeline de operaciones:</p><ol><li><strong>Cargar configuración</strong> — lee <code>swag2mcp.yaml</code> del espacio de trabajo</li><li><strong>Validar</strong> — ejecuta las mismas comprobaciones que <code>validate</code> (sintaxis YAML, estructura, alcance del archivo de especificación, formato, autenticación, cliente HTTP)</li><li><strong>Limpiar</strong> — elimina todo el contenido de <code>cache/</code> y <code>responses/</code></li><li><strong>Recargar en caché</strong> — descarga todos los archivos de especificación remotos y copia los archivos de especificación locales a la caché</li><li><strong>Reindexar</strong> — reconstruye el índice de búsqueda de texto completo para todos los endpoints</li><li><strong>Scripts de autenticación</strong> — crea scripts de autenticación de plantilla para especificaciones que usan <code>ScriptAuth</code></li><li><strong>Limpieza de huérfanos</strong> — elimina scripts de autenticación para especificaciones que ya no existen</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./my-workspace</span></span></code></pre></div><h2 id="que-sucede-con-las-colecciones-deshabilitadas" tabindex="-1">Qué sucede con las colecciones deshabilitadas <a class="header-anchor" href="#que-sucede-con-las-colecciones-deshabilitadas" aria-label="Permalink to &quot;Qué sucede con las colecciones deshabilitadas&quot;">​</a></h2><p>Las colecciones con <code>disable: true</code> se omiten por completo — no se almacenan en caché ni se indexan.</p><h2 id="verificacion-posterior-al-comando" tabindex="-1">Verificación posterior al comando <a class="header-anchor" href="#verificacion-posterior-al-comando" aria-label="Permalink to &quot;Verificación posterior al comando&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ls</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [path]</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Todas las especificaciones deberían seguir listadas y accesibles</span></span></code></pre></div><h2 id="matices" tabindex="-1">Matices <a class="header-anchor" href="#matices" aria-label="Permalink to &quot;Matices&quot;">​</a></h2><ul><li><strong>Sin auto-inicio:</strong> Si el archivo de configuración no existe, <code>update</code> devuelve un error: <code>&quot;configuration not found at &amp;lt;path&amp;gt;&quot;</code>. Ejecute <code>init</code> primero.</li><li><strong>Dependencia de red:</strong> Todas las URL de especificaciones remotas deben ser accesibles. Si alguna descarga falla, toda la actualización falla con un mensaje de error claro.</li><li><strong>Creación de scripts de autenticación:</strong> Si una especificación usa <code>ScriptAuth</code> y el script de plantilla no existe, <code>update</code> lo crea. Si la creación falla, la actualización falla.</li><li><strong><code>update</code> vs <code>clean</code>:</strong> <code>clean</code> solo elimina la caché. <code>update</code> elimina la caché <strong>y</strong> vuelve a descargar todo. Use <code>clean</code> cuando solo quiera liberar espacio; use <code>update</code> cuando quiera actualizar.</li></ul>`,21)])])}const g=e(t,[["render",c]]);export{u as __pageData,g as default};
